import {liveBoardEvidenceHTML} from './live-board-evidence.mjs?v=20261110-library';
/* Student-page layout, subject navigation, cumulative progress and Glows & Grows
   adapted from EDUCADE public/teacher.js at 1a49552d1d76d4d3d9f973369454331b0fe7ba7c. */
import {escape} from './workspace-shared.js';
import {learningTabs,classAxes,axisStats,summarizePractice,practiceRadarHTML,progressBar,estimatedProgressHTML,estimatedScaleKeyHTML} from './educade-assessment-view.js?v=20261111-unified';
import {learnerEvidence} from './assessment-model.mjs';
import {quizScoreHTML} from './quiz-results.js';
import {assessmentHTML} from './lesson-feedback-view.js';
export const studentAxes=(catalogue,scope)=>scope==='overall'?Object.entries(learningTabs).filter(([id])=>id!=='overall').map(([id,tab])=>({id,domain:tab.domain,section:tab.section,label:tab.name})):classAxes(catalogue,scope);
export function studentScopeRecords(catalogue,records,scope){
 if(scope==='overall')return records;
 const tab=learningTabs[scope],ids=new Set(catalogue.groups.filter(g=>g.domain===tab.domain&&(!tab.section||g.section===tab.section)).flatMap(g=>g.skills.map(s=>s.id)));
 return records.filter(r=>ids.has(r.skillId));
}
export function studentProgressHTML(records){
 const dated=records.filter(r=>Number.isInteger(r.week)&&r.week>=1&&r.week<=4);
 if(!dated.length)return '<p class="assessment-empty">Weekly progress will appear when dated skill responses are available.</p>';
 const values=Array.from({length:4},(_,i)=>{const upto=dated.filter(r=>r.week<=i+1);return {week:i+1,independent:summarizePractice(upto.filter(r=>!r.supported)).score,supported:summarizePractice(upto.filter(r=>r.supported)).score};});
 const x=i=>50+i*150,y=v=>188-v*1.5,line=type=>values.filter(v=>v[type]!==null).map(v=>`${x(v.week-1)},${y(v[type])}`).join(' ');
 return `<svg class="educade-student-progress" viewBox="0 0 550 225" role="img" aria-label="Cumulative independent and supported accuracy over four weeks">${[0,25,50,75,100].map(n=>`<line x1="50" y1="${y(n)}" x2="510" y2="${y(n)}"/><text x="38" y="${y(n)+4}" text-anchor="end">${n}</text>`).join('')}${['independent','supported'].map(type=>`<polyline class="${type}" points="${line(type)}"/>`).join('')}${values.map(v=>`<text x="${x(v.week-1)}" y="214" text-anchor="middle">Week ${v.week}</text>${['independent','supported'].map(type=>v[type]===null?'':`<circle class="${type}" cx="${x(v.week-1)}" cy="${y(v[type])}" r="4"/>`).join('')}`).join('')}</svg><details class="educade-chart-values"><summary>View chart values</summary><table><thead><tr><th>Week</th><th>Independent</th><th>Supported</th></tr></thead><tbody>${values.map(v=>`<tr><th>${v.week}</th><td>${v.independent===null?'No evidence':v.independent+'%'}</td><td>${v.supported===null?'No evidence':v.supported+'%'}</td></tr>`).join('')}</tbody></table></details>`;
}
const axisAction=(axis,scope)=>scope==='overall'?`data-profile-scope="${axis.id}"`:`data-profile-evidence="${escape(axis.id)}"`;
export function studentPageHTML({classId,className,student,students,catalogue,lessons,records,scope='overall',mode='radar',selectedSkill='',demo=false,virtual=false,enduringTargets='',boardEvidence=[],boardEvidenceUnavailable=false}){
 if(!student)return '<section class="assessment-card"><button type="button" class="text-button" data-back-class>← Back to class</button><h2>Student not found in this class</h2></section>';
 const own=records.filter(r=>r.learnerId===student.id),scoped=studentScopeRecords(catalogue,own,scope),stats=summarizePractice(scoped),axes=studentAxes(catalogue,scope),scores=axes.map(axis=>axisStats(catalogue,own,axis)),observed=scores.filter(s=>s.score!==null).length;
 const title=learningTabs[scope].name,ranked=axes.map((axis,i)=>({axis,stats:scores[i]})).filter(c=>c.stats.attempts).sort((a,b)=>a.stats.score-b.stats.score),lessonsWithEvidence=learnerEvidence(lessons,student.id);
 const chart=mode==='radar'&&observed>=3?practiceRadarHTML(axes,scores.map(s=>s.score)):axes.map((axis,i)=>`<button type="button" class="educade-student-skill" ${axisAction(axis,scope)}><span>${escape(axis.label)}</span>${mode==='standards'?estimatedProgressHTML(scores[i].score,axis.label):progressBar(scores[i].score,axis.label)}</button>`).join('');
 const choices=axes.map((axis,i)=>`<button type="button" ${axisAction(axis,scope)}><span>${escape(axis.label)}</span><strong>${scores[i].score===null?'No evidence yet':scores[i].score+'%'}</strong></button>`).join('');
 const groups=catalogue.groups.filter(g=>scope==='overall'||g.domain===learningTabs[scope].domain&&(!learningTabs[scope].section||g.section===learningTabs[scope].section));
 const selected=catalogue.groups.flatMap(g=>g.skills).find(s=>s.id===selectedSkill),responses=own.filter(r=>r.skillId===selectedSkill).slice().reverse();
 return `<section class="educade-student-page"><header class="educade-student-heading"><div class="educade-student-identity"><span class="educade-avatar" aria-hidden="true">${escape(student.initials||student.name.split(' ').map(w=>w[0]).join(''))}</span><div><p>${escape(className)} / Student profile${demo?' · Fictional learner':''}</p><div class="educade-student-navigation"><select data-switch-learner data-student-page-title aria-label="Switch learner">${students.map(s=>`<option value="${escape(s.id)}" ${s.id===student.id?'selected':''}>${escape(s.name)}</option>`).join('')}</select><button type="button" class="teacher-button secondary" data-back-class>← Back to class</button>${virtual?'':`<a class="teacher-button" href="/notebooks?${new URLSearchParams({classId,notebookId:classId+'.'+student.id})}">Open notebooks ↗</a>`}</div></div></div></header><div class="educade-learning-tabs" role="tablist" aria-label="Student learning domains">${Object.entries(learningTabs).map(([id,tab])=>`<button type="button" role="tab" data-profile-scope="${id}" aria-selected="${scope===id}" tabindex="${scope===id?'0':'-1'}">${tab.name}</button>`).join('')}</div><div class="educade-student-grid"><div class="educade-student-column"><section class="assessment-card"><div class="assessment-card-heading"><h2>${escape(title)} profile</h2><div class="educade-mode-switch" role="group" aria-label="Student chart view">${[['bars','Progress bars'],['radar','Radar chart'],['standards','Standards progress']].map(([id,label])=>`<button type="button" data-student-mode="${id}" aria-pressed="${mode===id}">${label}</button>`).join('')}</div></div><div class="educade-student-summary"><span>Practice accuracy</span><strong>${stats.score===null?'No evidence yet':stats.score+'%'}</strong></div>${mode==='standards'?estimatedScaleKeyHTML():''}${chart}${mode==='radar'&&observed>=3?`<div class="educade-student-score-grid">${choices}</div>`:''}<p class="assessment-footnote">${observed<3&&mode==='radar'?'A radar needs at least three areas with evidence. ':''}${mode==='standards'?'B–M+ levels are provisional estimates from practice accuracy.':'Practice accuracy uses recorded responses.'} Missing evidence is excluded.</p></section>${selected?`<section class="assessment-card" id="student-response-evidence" tabindex="-1"><h2>${escape(selected.name)}</h2><p>${responses.length} linked responses</p>${responses.length?`<div class="educade-response-list">${responses.map(r=>`<article><p>${escape(r.response||'Recorded response')}</p><small>${r.correct?'Correct':'Review response'} · ${r.supported?'Supported':'Independent'}${r.hint?' · Hint used':''}${r.week?' · Week '+escape(r.week):''}</small></article>`).join('')}</div>`:'<p>No responses recorded for this skill yet.</p>'}</section>`:''}${liveBoardEvidenceHTML(boardEvidence,{classId,learnerId:student.id,unavailable:boardEvidenceUnavailable})}<section class="assessment-card assessment-detail"><h2>Lesson evidence</h2>${lessonsWithEvidence.length?lessonsWithEvidence.slice().reverse().map(({lesson,quiz,assessment})=>`<details class="assessment-lesson"><summary>${escape(lesson.title)}<small>${escape(lesson.date||'')}</small></summary>${quiz?.latest?quizScoreHTML(quiz):''}${assessment?assessmentHTML(assessment):''}</details>`).join(''):'<p>No published lesson assessments yet.</p>'}${virtual?'':'<button type="button" class="teacher-button secondary" data-assessment-timeline>Open class timeline</button>'}</section></div><div class="educade-student-column"><section class="assessment-card"><h2>Progress over four weeks</h2><p class="assessment-footnote">Cumulative accuracy for recorded skill practice.</p><div class="educade-student-legend"><span>Independent</span><span>Supported</span></div>${studentProgressHTML(scoped)}</section><section class="assessment-card"><h2>Glows &amp; Grows</h2>${[['Glows',ranked.at(-1)],['Grows',ranked[0]]].map(([label,choice])=>`<article class="educade-growth ${label==='Grows'?'grow':''}"><p>${label}</p><h3>${choice?escape(choice.axis.label):'No evidence yet'}</h3>${choice?`<strong>${choice.stats.score}% correct</strong><span> · ${choice.stats.correct}/${choice.stats.attempts} responses</span><p>${label==='Glows'?'A relative strength in recorded practice.':'Practise this area, then check a fresh response independently.'}</p><button type="button" class="text-button" ${axisAction(choice.axis,scope)}>Explore ${label==='Glows'?'this strength':'this target'} →</button>`:'<p>Collect a response before choosing a focus.</p>'}</article>`).join('')}<div class="educade-support-totals"><div><strong>${stats.independent}</strong><span>independent answers</span></div><div><strong>${stats.supported}</strong><span>supported answers</span></div><div><strong>${stats.hints}</strong><span>answers with a hint</span></div></div><p class="assessment-footnote">Hint use is included in supported answers.</p></section>${enduringTargets?`<section class="assessment-card"><h2>Enduring understandings</h2><p>${escape(enduringTargets)}</p></section>`:''}</div></div><section class="assessment-card educade-student-catalogue"><h2>Individual skill catalogue</h2>${groups.map(group=>`<details class="assessment-skill-group"><summary>${escape(group.name)}</summary><div class="educade-student-score-grid">${group.skills.map(skill=>{const result=axisStats(catalogue,own,skill);return `<button type="button" data-profile-evidence="${escape(skill.id)}"><span>${escape(skill.name)}</span><strong>${result.score===null?'No evidence yet':result.score+'%'}</strong></button>`;}).join('')}</div></details>`).join('')}</section></section>`;
}
